MOD = 10**9 + 7

def catalan(n):
    if n == 0:
        return 1
    res_num = 1
    res_den = 1
    for i in range(2, n + 1):
        res_num *= (n + i)
        res_den *= i
    return res_num // res_den % MOD

def count_sequences(n, s):
    def dp(i, j, open_count):
        if i == len(s):
            if j == 2 * n and open_count == 0:
                return 1
            return 0
        if j == 2 * n or open_count < 0:
            return 0
        if (i, j, open_count) in memo:
            return memo[(i, j, open_count)]

        result = 0
        if s[i] == '(':
            result = dp(i + 1, j + 1, open_count + 1)
        elif s[i] == ')':
            result = dp(i + 1, j + 1, open_count - 1)
        else:
            result = dp(i + 1, j + 1, open_count + 1) + dp(i + 1, j + 1, open_count - 1)

        memo[(i, j, open_count)] = result % MOD
        return result

    memo = {}
    total_sequences = catalan(n)
    valid_sequences = dp(0, 0, 0)

    return (total_sequences - valid_sequences + MOD) % MOD

import sys
input = sys.stdin.read
